                    # Find nearest component center to arrow
                    arrow_centroid = compute_centroid(arrow_cl)

                    dist1 = min_manhattan_dist(cl1, arrow_cl)
                    dist2 = min_manhattan_dist(cl2, arrow_cl)

                    # Recolor farther twin
                    for y, x in cl2:
                        if grid[y, x] != bg:
                            grid[y, x] = arrow_color
